// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";

import { clientPointToViewport } from "../../../main/frontend/graph-explorer/graph-viewport.ts";
import { fitBoxes } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { zoomTransformAt } from '../../../main/frontend/graph-explorer/graph-viewport.ts';

test('Fit includes distant nodes even in a graph below 500 nodes', () => {
  const boxes = [{x: -5000, y: -5000, width: 280, height: 46}, {x: 5000, y: 5000, width: 280, height: 46}];
  const transform = fitBoxes(boxes);
  for (const b of boxes) {
    assert.ok((b.x - b.width / 2) * transform.k + transform.x >= 0);
    assert.ok((b.x + b.width / 2) * transform.k + transform.x <= 1280);
    assert.ok((b.y - b.height / 2) * transform.k + transform.y >= 0);
    assert.ok((b.y + b.height / 2) * transform.k + transform.y <= 780);
  }
});

test('zooming out from an overview never jumps in to the old minimum zoom', () => {
  const initial = {x: 100, y: 100, k: .05};
  assert.ok(zoomTransformAt(initial, .9, {x: 640, y: 390}).k < initial.k);
});

test("client focal points stay finite when a canvas temporarily has no size", () => {
  const point = clientPointToViewport(
    24,
    18,
    { left: 10, top: 8, width: 0, height: 0 },
    { width: 1280, height: 780 },
  );
  assert.deepEqual(point, { x: 14, y: 10 });
  assert.ok(Number.isFinite(point.x) && Number.isFinite(point.y));
});

import { revealPoint, visibleArea } from "../../../main/frontend/graph-explorer/graph-viewport.ts";

const VIEW = { width: 1280, height: 780 };
const rect = (left, top, width, height) => ({ left, top, width, height, right: left + width, bottom: top + height });

test("the visible area leaves out a card on the right, or a sheet along the bottom", () => {
  // A 1280 x 780 canvas at its own size, with a 340px card on the right.
  assert.deepEqual(visibleArea(rect(0, 0, 1280, 780), rect(928, 12, 340, 400), VIEW), { left: 0, top: 0, right: 916, bottom: 780 });
  // A 390 x 600 phone canvas (the view box is scaled to its width and letterboxed vertically), with a bottom sheet.
  const phone = visibleArea(rect(0, 0, 390, 600), rect(8, 300, 374, 292), VIEW);
  const scale = 390 / 1280;
  assert.equal(phone.left, 0);
  assert.equal(phone.right, 1280);
  assert.ok(Math.abs(phone.top - (-(600 / scale - 780) / 2)) < 1e-9, "the letterbox above the view box is visible too");
  assert.ok(Math.abs(phone.bottom - (300 / scale - (600 / scale - 780) / 2)) < 1e-9, "down to the sheet");
  assert.deepEqual(visibleArea(rect(0, 0, 1280, 780), null, VIEW), { left: 0, top: 0, right: 1280, bottom: 780 });
});

test("revealing a point centres it in the visible area, unless it is already well inside", () => {
  const area = { left: 0, top: -200, right: 1280, bottom: 300 };
  const moved = revealPoint({ x: 500, y: 600 }, { x: 0, y: 0, k: 1 }, area);
  assert.deepEqual(moved, { x: 640 - 500, y: 50 - 600, k: 1 });
  assert.equal(revealPoint({ x: 640, y: 50 }, { x: 0, y: 0, k: 1 }, area), null);
  assert.deepEqual(revealPoint({ x: 100, y: 150 }, { x: 0, y: 0, k: 2 }, area), { x: 640 - 200, y: 50 - 300, k: 2 });
});
